logger.message:
#[%dw 2.0 
output application/json 
--- { 
	correlationId: vars.correlationId, 
	stagingCount: sizeOf(vars.stagingInvoices default [])
}]

ee:variables.ee:set-variable:
output application/json
---
{
    "method"  : "POST",
    "host"    : Mule::p('linka.host'),
    "port"    : Mule::p('linka.port'),
    "path"    : Mule::p('linka.path.token'),
    "basePath": Mule::p('linka.basePath'),
    "queryParams": {
        "key"  : Mule::p('secure::linka.username'),
        "value": Mule::p('secure::linka.password')
    }
}

set-variable.value:
#[output application/json
---
{
    "method"      : "GET",
    "host"        : Mule::p("linka.host"),
    "port"        : Mule::p("linka.port"),
    "path"        : Mule::p("linka.path.invoices"),
    "basePath"    : Mule::p("linka.basePath"),
    "queryParams" : {
        "sn": vars.currentStagingRow.id
    },
    "headers": {
        "Authorization": "Bearer " ++ vars.accessToken.access
    }
}]
